Given a Binary Tree, the task is to print the diagonal traversal of the binary tree.Note: If the diagonal element are present in two different subtrees, then left subtree diagonal element should be taken first and then right subtree. Example:Input:  Output: 8 10 14 3 6 7 13 1 4Explanation: The above is the diagonal elements in a binary tree that belong to the same line.Table of Content[Expected Approach - 1] Using Queue with delimiter - O(n) Time and O(n) Space[Expected Approach - 2] Using Queue without delimiter - O(n) Time and O(n) Space[Expected Approach - 1] Using Queue with delimiter - O(n) Time and O(n) SpaceThe idea is to traverse the binary tree in level order manner using a queue. Push the root node and null pointer into the queue. For each node (starting from root), append its value to the resultant list. Push its left child node into queue if it exists, and set it to its right child node. If the current node is null, it means the starting of the next diagonal. So set the current node to the front node of the queue and pop from queue. Below is the implementation of the above approach:
            C++

    // C++ program to print diagonal view
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Iterative function to print diagonal view
vector<int> diagonal(Node* root) {
    vector<int> ans;

    // base case
    if (root == nullptr)
        return ans;

    queue<Node*> q;

    q.push(root);

    q.push(nullptr);

    while (!q.empty()) {

        Node* curr = q.front();
        q.pop();

        // if current is delimiter then insert another
        // null for next diagonal 
        if (curr == nullptr) {

            // if tree has been traversed
            if (q.empty()) break;

            q.push(nullptr);
        }

        // Else print the current diagonal
        else {
            while (curr != nullptr) {
                ans.push_back(curr->data);

                // if left child is present 
                // push into queue
                if (curr->left != nullptr)
                    q.push(curr->left);

                // current equals to right child
                curr = curr->right;
            }
        }
    }

    return ans;
}

void printList(vector<int> v) {
    int n = v.size();
    for (int i=0; i<n; i++) {
        cout << v[i] << " ";
    }
    cout << endl;
}

int main() {

    // Create a hard coded tree
    //         8
    //       /   \
    //     3      10
    //    /      /  \
    //   1      6    14
    //         / \   /
    //        4   7 13
    Node* root = new Node(8);
    root->left = new Node(3);
    root->right = new Node(10);
    root->left->left = new Node(1);
    root->right->left = new Node(6);
    root->right->right = new Node(14);
    root->right->right->left = new Node(13);
    root->right->left->left = new Node(4);
    root->right->left->right = new Node(7);

    vector<int> ans = diagonal(root);
    printList(ans);
}


